ory usage: {initial_memory:.2f} MB\\\")\\n    \\n    # Check that zarr chunks are in encoding\\n    temp_var = ds['temperature']\\n    encoding_chunks = temp_var._variable.encoding.get('preferred_chunks')\\n    print(f\\\"Zarr chunks in encoding: {encoding_chunks}\\\")\\n    assert encoding_chunks == {'x': 200, 'y': 200}, f\\\"Expected chunks in encoding, got {encoding_chunks}\\\"\\n    \\n    # Access chunks - this should NOT load the entire array\\n    print(\\\"Accessing ds.chunks...\\\")\\n    chunks_result = ds.chunks\\n    print(f\\\"Chunks result: {chunks_result}\\\")\\n    \\n    # Check memory usage after accessing chunks\\n    current, peak = tracemalloc.get_traced_memory()\\n    final_memory = current / 1024 / 1024\\n    memory_increase = final_memory - initial_memory\\n    print(f\\\"Memory usage after chunks access: {final_memory:.2f} MB\\\")\\n    print(f\\\"Memory increase: {memory_increase:.2f} MB\\\")\\n    \\n    # Verify chunks are correctly detected\\n    expected_chunks = {'x': (200,), 'y': (200,)}\\n    assert chunks_result == expected_chunks, f\\\"Expected {expected_chunks}, got {chunks_result}\\\"\\n    \\n    # Verify memory usage didn't increase significantly (should be < 50MB)\\n    assert memory_increase < 50, f\\\"Memory increased by {memory_increase:.2f} MB, which suggests array was loaded\\\"\\n    \\n    tracemalloc.stop()\\n    \\n    # Clean up\\n    import shutil\\n    shutil.rmtree(temp_dir)\\n    \\n    print(\\\"\\u2713 SUCCESS: Zarr chunks accessed without loading entire array into memory\\\")\\n    print(f\\\"\\u2713 Chunks correctly detected: {chunks_result}\\\")\\n    print(f\\\"\\u2713 Memory usage remained low: {memory_increase:.2f} MB increase\\\")\\n\\nif __name__ == \\\"__main__\\\":\\n    test_zarr_chunks_no_memory_load()\"}", "name": "str_replace_editor"}

