    if modname:
        if 'property' in self.options:
            return _('%s (in module %s)') % (name, modname)  # ✅ No parentheses for properties
        else:
            return _('%s() (in module %s)') % (name, modname)
    else:
        if 'property' in self.options:
            return '%s' % name  # ✅ No parentheses for properties
        else:
            return '%s()' % name

if 'classmethod' in self.options:
